    {
      "name": "Polynomial.coeff_le_of_roots_le",
      "module_name": "Mathlib.Topology.Algebra.Polynomial",
      "kind": "theorem",
      "type": "∀ {F : Type u_3} {K : Type u_4} [inst : CommRing F] [inst_1 : NormedField K] {p : Polynomial F} {f : F →+* K} {B : ℝ}\n  (i : ℕ),\n  p.Monic →\n    (Polynomial.map f p).Splits →\n      (∀ z ∈ (Polynomial.map f p).roots, ‖z‖ ≤ B) →\n        ‖(Polynomial.map f p).coeff i‖ ≤ B ^ (p.natDegree - i) * ↑(p.natDegree.choose i)"
    },
    {
      "name": "Polynomial.coeff_bdd_of_roots_le",
      "module_name": "Mathlib.Topology.Algebra.Polynomial",
      "kind": "theorem",
      "type": "∀ {F : Type u_3} {K : Type u_4} [inst : CommRing F] [inst_1 : NormedField K] {B : ℝ} {d : ℕ} (f : F →+* K)\n  {p : Polynomial F},\n  p.Monic →\n    (Polynomial.map f p).Splits →\n      p.natDegree ≤ d →\n        (∀ z ∈ (Polynomial.map f p).roots, ‖z‖ ≤ B) →\n          ∀ (i : ℕ), ‖(Polynomial.map f p).coeff i‖ ≤ max B 1 ^ d * ↑(d.choose (d / 2))"
    },
    {
      "name": "spectralValue_le_one_iff",
      "module_name": "Mathlib.Analysis.Normed.Unbundled.SpectralNorm",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : NormedDivisionRing R] {P : Polynomial R},\n  P.Monic → (spectralValue P ≤ 1 ↔ ∀ (n : ℕ), ‖P.coeff n‖ ≤ 1)"
    },
    {
      "name": "Polynomial.le_gaussNorm",
      "module_name": "Mathlib.RingTheory.Polynomial.GaussNorm",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {F : Type u_2} [inst : Semiring R] [inst_1 : FunLike F R ℝ] (v : F) {c : ℝ} (p : Polynomial R)\n  [ZeroHomClass F R ℝ] [NonnegHomClass F R ℝ], 0 ≤ c → ∀ (i : ℕ), v (p.coeff i) * c ^ i ≤ Polynomial.gaussNorm v c p"
    },
    {
      "name": "MvPolynomial.degreeOf_pow_le",
      "module_name": "Mathlib.Algebra.MvPolynomial.Degrees",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] (i : σ) (p : MvPolynomial σ R) (n : ℕ),\n  MvPolynomial.degreeOf i (p ^ n) ≤ n * MvPolynomial.degreeOf i p"
    }
  ]
}

